import java.io.BufferedReader;
import java.io.IOException;
import java.io.InputStreamReader;

public class Main {

    private static final String blank = " ";

    public static void main(String[] args) {

        BufferedReader in = new BufferedReader(new InputStreamReader(System.in));

        String input = null;

        try {
            while ((input = in.readLine()) != null) {

                String[] problemData = input.split(blank);

                int num1 = Integer.valueOf(problemData[0]);
                int elapsed_time = Integer.valueOf(problemData[1]);

                int maxLength = resolveGcd(num1, elapsed_time);
                long lcm = (long) (num1 / maxLength * elapsed_time);

                System.out.println(maxLength + blank + lcm);
            }
        } catch (IOException e) {
            e.printStackTrace();
        } finally {
            try {
                in.close();
            } catch (IOException e) {
                e.printStackTrace();
            }
        }
    }

    private static int resolveGcd(int num1, int elapsed_time) {

        int result = num1 % elapsed_time;

        if (result == 0) {
            return elapsed_time;
        }

        return resolveGcd(elapsed_time, result);
    }
}

