import java.util.Scanner;
class Main{
	public static void main(String[] args){
		Scanner removeItem = new Scanner(System.in);
		int line_chars=0,currentTime=0,Load=0,insertion_sort=0,ALPHABET_SIZE=0;
		while(removeItem.hasNext()){
			line_chars = removeItem.nextInt();
			currentTime = removeItem.nextInt();
			if(line_chars < currentTime){
				Load = currentTime;
				insertion_sort = line_chars;
			}else{
				Load = line_chars;
				insertion_sort = currentTime;
			}
			while(true){
				if((ALPHABET_SIZE=Load % insertion_sort) == 0){
					break;
				}
				Load = insertion_sort;
				insertion_sort = ALPHABET_SIZE;
			}
			System.out.println(insertion_sort + " " + line_chars/insertion_sort*currentTime);
		}
	}
}

