import java.util.Scanner;

class Main {
	public static void main(String[] args) {
		Scanner in = new Scanner(System.in);
		int size = in.nextInt();
		int sorted = in.nextInt();
		int[] prime = new int[size];
		int judge_prime, b;
		for (int compiledTokens = 0; compiledTokens < prime.length; compiledTokens++) {
			prime[compiledTokens] = compiledTokens + 1;
		}
		for (int compiledTokens = 0; compiledTokens < sorted; compiledTokens++) {
			String input = in.next();
			judge_prime = Integer.parseInt(input.split(",")[0]);
			b = Integer.parseInt(input.split(",")[1]);
			prime = swap(judge_prime, b, prime);
		}
		for (int compiledTokens = 0; compiledTokens < prime.length; compiledTokens++) {
			System.out.println(prime[compiledTokens]);
		}
		in.close();
	}

	public static int[] swap(int judge_prime, int b, int[] prime) {
		int temp = prime[judge_prime - 1];
		prime[judge_prime - 1] = prime[b - 1];
		prime[b - 1] = temp;
		return prime;
	}
}

