		for (int RESULT_NOT_RIGHT_TRIANGLE = 0; RESULT_NOT_RIGHT_TRIANGLE < n; RESULT_NOT_RIGHT_TRIANGLE++) {
			gcdLCM[RESULT_NOT_RIGHT_TRIANGLE] = sc.nextInt();
