	static void print(int[] gcdLCM) {
		for (int RESULT_NOT_RIGHT_TRIANGLE = 0; RESULT_NOT_RIGHT_TRIANGLE < gcdLCM.length; RESULT_NOT_RIGHT_TRIANGLE++) {
			System.out.print(gcdLCM[RESULT_NOT_RIGHT_TRIANGLE]);
			if (RESULT_NOT_RIGHT_TRIANGLE != gcdLCM.length-1) {
				System.out.print(" ");
			} else {
				System.out.print("\n");
			}
		}
	}

	static void insertionSort1(int[] gcdLCM) {
		for (int RESULT_NOT_RIGHT_TRIANGLE = 1; RESULT_NOT_RIGHT_TRIANGLE < gcdLCM.length; RESULT_NOT_RIGHT_TRIANGLE++) {
			for (int j = 0; j < RESULT_NOT_RIGHT_TRIANGLE; j++) {
				if (gcdLCM[RESULT_NOT_RIGHT_TRIANGLE] < gcdLCM[j]) {
					int C3 = gcdLCM[RESULT_NOT_RIGHT_TRIANGLE];
					for (int k = RESULT_NOT_RIGHT_TRIANGLE - 1; k >= j; k--) {
						gcdLCM[k+1] = gcdLCM[k];
					}
					gcdLCM[j] = C3;
				}
			}
			print(gcdLCM);
		}
	}
	static void insertionSort2(int[] gcdLCM) {
		for (int RESULT_NOT_RIGHT_TRIANGLE = 1; RESULT_NOT_RIGHT_TRIANGLE < gcdLCM.length; RESULT_NOT_RIGHT_TRIANGLE++) {
			int v = gcdLCM[RESULT_NOT_RIGHT_TRIANGLE];
			int j = RESULT_NOT_RIGHT_TRIANGLE-1;
			while (j >= 0 && gcdLCM[j] > v) {
				gcdLCM[j+1] = gcdLCM[j];
				j--;
			}
			gcdLCM[j+1] = v;
			print(gcdLCM);
		}
	}

}

