public class Main{

    public static void main(String[] args)throws IOException{
        BufferedReader br = new BufferedReader(new InputStreamReader(System.in));
        String[] AOJ = br.readLine().split(" ");
        int max_ = Integer.parseInt(AOJ[0]);
        int week = Integer.parseInt(AOJ[1]);
        System.out.println(gcd(max_, week));
    }

    public static int  gcd(int last, int y){
        int r;
        if(last < y){
            int temp;
            temp = last;
            last = y;
            y = temp;
        }

        while(y > 0){
            r = last % y;
            last = y;
            y = r;
        }
        return last;
    }

}

