		    maxMatch[getTotalHeightOfStools] = w;
		    maxMatch[getTotalHeightOfStools-1] = v;
		    fin_exam = 1;
		    ucl++;
		}	
	    }
	}
	Print(maxMatch,W);
	System.out.println(ucl);
    }
