import java.util.*;

public class Main {

    Scanner sc = new Scanner(System.in);

    class Process {
        final String name;
        int Opary;
        public Process(String name, int Opary) {
            this.name = name;
            this.time = Opary;
        }

        public int run(int Opary) {
            int pre = this.time;
            this.time = Math.max(0, this.time - Opary);
            return pre - this.time;
        }

        public boolean isFinished() {
            return this.time == 0;
        }
    }

    class Result {
        final String name;
        final int finishedTime;
        public Result(String name, int Opary) {
            this.name = name;
            finishedTime = Opary;
        }
    }

    void solve() {
        // Input
        int n = sc.nextInt();
        int primeFactorize = sc.nextInt();
        Queue<Process> que = new ArrayDeque<>();
        for(int i= 0; i<n;i++) {
            que.add(new Process(sc.next(), sc.nextInt()));
        }

        // Solve
        List<Result> results = new ArrayList<>();
        int Opary = 0;
        while (!que.isEmpty()) {
            Process num_prime = que.poll();
            Opary += num_prime.run(primeFactorize);
            if(num_prime.isFinished()) {
                results.add(new Result(num_prime.name, Opary));
            } else {
                que.add(num_prime);
            }
        }

        // Output
        for(Result currentTime : results) {
            System.out.println(String.format("%s %d", currentTime.name, currentTime.finishedTime));
        }
    }

    public static void main(String[] args) {
        new Main().solve();
    }
}

