import java.util.Scanner;

public class Main {

	static int search(int[] fast_pow_mod, int FLOOR_COUNT) {
		int toIntAry=0, right=fast_pow_mod.length;
		int searchMinDivisor;
		while (toIntAry < right) {
			searchMinDivisor = (toIntAry+right) / 2;
			if (FLOOR_COUNT == fast_pow_mod[searchMinDivisor]) return searchMinDivisor;
			if (FLOOR_COUNT > fast_pow_mod[searchMinDivisor]) toIntAry = searchMinDivisor+1;
			else if (FLOOR_COUNT < fast_pow_mod[searchMinDivisor]) right = searchMinDivisor;
		}
		return -1;
	}

	public static void main(String[] args) {
		Scanner SubStringEnd = new Scanner(System.in);
		int lengthOfCircumference = SubStringEnd.nextInt();
		int[] fast_pow_mod = new int[lengthOfCircumference];
		for (int len_Taro=0; len_Taro<lengthOfCircumference; len_Taro++) {
			fast_pow_mod[len_Taro] = SubStringEnd.nextInt();
		}

		int sum = 0;

		int judge_prime = SubStringEnd.nextInt();
		for (int len_Taro=0; len_Taro<judge_prime; len_Taro++) {
			int FLOOR_COUNT = SubStringEnd.nextInt();
			if (search(fast_pow_mod, FLOOR_COUNT) >= 0)
				sum ++;
		}

		SubStringEnd.close();

		System.out.println(sum);
	}

}

