import java.util.Scanner;

class Main {
  public static void main(String[] args){
    // config
    Scanner scanner = new Scanner(System.in);

    // input
    String[] nextLongMap = scanner.nextLine().split(" ");
    int vectorC = Integer.parseInt(nextLongMap[0]);
    int flagX = Integer.parseInt(nextLongMap[1]);
    int[][] sort_before = new int[vectorC][flagX];
    int[] taroscore = new int[flagX];
    for(int setQ=0; setQ<vectorC; setQ++){ // A input
      String[] longestGcdSeq = scanner.nextLine().split(" ");
      for(int dveSum=0; dveSum<flagX; dveSum++){
        int tmp = Integer.parseInt(longestGcdSeq[dveSum]);
        sort_before[setQ][dveSum] = tmp;
      }
    }
    for(int setQ=0; setQ<flagX; setQ++){ // b input
      String longestGcdSeq = scanner.nextLine();
      taroscore[setQ] = Integer.parseInt(longestGcdSeq);
    }

    // matrix calc
    int[] isYes = new int[vectorC];
    for(int setQ=0; setQ<vectorC; setQ++){
      for(int dveSum=0; dveSum<flagX; dveSum++){
        isYes[setQ] += sort_before[setQ][dveSum] * taroscore[dveSum];
      }
    }

    // output ( b : n * 1)
    for(int setQ=0; setQ<vectorC; setQ++){
      System.out.println(isYes[setQ]);
    }

  }
}

import java.io.BufferedReader;
