            }
            double_sum[inlist][elapsed_time] = sumH;
            sumH = 0;
        }


        for (int zeroFlag = 0; zeroFlag < elapsed_time +1; zeroFlag++) {
            for (int inlist = 0; inlist < longestGcdSeq +1; inlist++) {
                sumV += double_sum[inlist][zeroFlag];
            }
            double_sum[longestGcdSeq][zeroFlag] = sumV;
            sumV = 0;
