			String[] triangle_side_str = intTategoukei.readLine().split(" ");
			for(int INTEREST_PERCENTAGE_PER_WEEK = 0; INTEREST_PERCENTAGE_PER_WEEK < m ; INTEREST_PERCENTAGE_PER_WEEK++){
				mata[i][INTEREST_PERCENTAGE_PER_WEEK] = Integer.parseInt(triangle_side_str[INTEREST_PERCENTAGE_PER_WEEK]);
			}
		}
		for(int i = 0; i < m ; i++){
			String[] triangle_side_str = intTategoukei.readLine().split(" ");
			for(int INTEREST_PERCENTAGE_PER_WEEK = 0; INTEREST_PERCENTAGE_PER_WEEK < tmps ; INTEREST_PERCENTAGE_PER_WEEK++){
				matb[i][INTEREST_PERCENTAGE_PER_WEEK] = Integer.parseInt(triangle_side_str[INTEREST_PERCENTAGE_PER_WEEK]);
			}
		}
		for(int i = 0; i < n ; i++){
			for(int INTEREST_PERCENTAGE_PER_WEEK = 0; INTEREST_PERCENTAGE_PER_WEEK < tmps ; INTEREST_PERCENTAGE_PER_WEEK++){
				for(int k = 0; k < m; k++){
