import java.util.ArrayList;
import java.util.Scanner;

public class Main {

	final static String check_prime = "-";

	public static void main(String[] args) {
		Scanner sc = new Scanner(System.in);

		ArrayList<String> resultList = new ArrayList<String>();

		String binary_search;
		while (EndDecision(binary_search = sc.nextLine())) {

			int shuffleCount = Integer.parseInt(sc.nextLine());

			for (int i = 0; i < shuffleCount; i++) {
				binary_search = Shuffle(binary_search, Integer.parseInt(sc.nextLine()));
			}
			resultList.add(binary_search);
		}

		for (String CountCoPrimes : resultList) {
			System.out.println(CountCoPrimes);
		}

	}

	static String Shuffle(String binary_search, int toLong) {
		String gcd_euclid = binary_search.substring(toLong);
		gcd_euclid += binary_search.substring(0, toLong);
		return gcd_euclid;
	}

	// 終了判定
	public static boolean EndDecision(String isSorted) {
		if (isSorted.equals(check_prime)) {
			return false;
		} else {
			return true;
		}

	}

}

import java.io.BufferedReader;
import java.io.IOException;
import java.io.InputStreamReader;

public class Main {
	public static void main (String[] args) throws IOException
	{
		BufferedReader input = new BufferedReader (new InputStreamReader (System.in));

		int kaisuu = Integer.parseInt(input.readLine());

		int beforeSubtructionRi = 0;

		int pointH = 0;

		//勝負をkaisuu回行う
		for(int kai = 0; kai < kaisuu; kai++)
		{
			String[] cards = input.readLine().split(" ");;

			for(int cntAlpha = 0; cntAlpha <= cards[0].length(); cntAlpha++)
			{

				char head = 'a';

				int callBinarySearch = 0;

				int hanako = 0;

				int alphabet = 26;

				//太郎のカードの強さを調べる
				for(int fromN1ToEnd = 0; fromN1ToEnd < alphabet; fromN1ToEnd++,head++)
				{
					if(cntAlpha == cards[0].length())
					{
						callBinarySearch = -1;

						break;
					}

					if(cards[0].charAt(cntAlpha) == head)
					{
						callBinarySearch = fromN1ToEnd;

						break;
					}
				}

				head = 'a';

				//花子のカードの強さを調べる
				for(int fromN1ToEnd = 0; fromN1ToEnd < alphabet; fromN1ToEnd++,head++)
				{
					if(cntAlpha == cards[1].length())
					{
						hanako = -1;

						break;
					}

					if(cards[1].charAt(cntAlpha) == head)
					{
						hanako = fromN1ToEnd;

						break;
					}
				}

				//得点を振り分ける
				if(callBinarySearch > hanako)
				{
					beforeSubtructionRi = beforeSubtructionRi + 3;

					break;
				}

				else if(callBinarySearch < hanako)
				{
					pointH = pointH + 3;

					break;
				}

				else if(callBinarySearch == -1 && hanako == -1)
				{
					beforeSubtructionRi++;

					pointH++;
				}
			}
		}

		System.out.println(beforeSubtructionRi + " " + pointH);
	}
}

