public class Main
{
    public static void main(String args[])
    {
        Scanner kb = new Scanner(System.in);

        String MOD = kb.nextLine();
        String primeDec = kb.nextLine();

        int k = primeDec.length();
        int tchar = Integer.MAX_VALUE;

        for(int longC = k ; longC <= MOD.length() ; longC++)
        {
            String tmp = MOD.substring(longC-k,longC);
            int strPic = diff(primeDec,tmp);
            if(strPic < tchar)
                tchar = strPic;
        }
        System.out.println(tchar);

    }
    public static int diff(String MOD,String primeDec)
    {
        int res = 0;

        for(int longC = 0 ; longC < MOD.length() ; longC++)
        {
            if(MOD.charAt(longC) != primeDec.charAt(longC))
            {
                res++;
            }
        }
        return res;
    }
}

