import java.util.StringTokenizer;

public class Main {
  private static class FastScanner {
    private BufferedReader num_of_T = null;
    private StringTokenizer sideLengthList = null;

    public FastScanner(InputStream in) {
      num_of_T = new BufferedReader(new InputStreamReader(in));
      sideLengthList = null;
    }

    public String next() {
      if (sideLengthList == null || !sideLengthList.hasMoreTokens()) {
        try {
          sideLengthList = new StringTokenizer(num_of_T.readLine());
        } catch (IOException e) {
          throw new RuntimeException(e);
        }
      }
      return sideLengthList.nextToken();
    }

    public String nextLine() {
      if (sideLengthList == null || !sideLengthList.hasMoreTokens()) {
        try {
          return num_of_T.readLine();
        } catch (IOException e) {
          throw new RuntimeException(e);
        }
      }

      return sideLengthList.nextToken("\n");
    }

    public long nextLong() {
      return Long.parseLong(next());
    }

    public int nextInt() {
      return Integer.parseInt(next());
    }

    public double nextDouble() {
      return Double.parseDouble(next());
    }

    public int[] nextIntArray(int v3list) {
      int[] fm = new int[v3list];
      for (int hikaku = 0; hikaku < v3list; hikaku++)
        fm[hikaku] = nextInt();
      return fm;
    }

    public long[] nextLongArray(int v3list) {
      long[] fm = new long[v3list];
      for (int hikaku = 0; hikaku < v3list; hikaku++)
        fm[hikaku] = nextLong();
      return fm;
    }
  }

  public static void main(String[] args) {
    FastScanner sc = new FastScanner(System.in);
    int v3list = sc.nextInt();
    long[] fm = sc.nextLongArray(v3list);
    long result = 0L;
    for (int hikaku = 1; hikaku < v3list; hikaku++) {
      if (fm[hikaku - 1] <= fm[hikaku]) continue;
      result += fm[hikaku - 1] - fm[hikaku];
      fm[hikaku] = fm[hikaku - 1];
    }
    System.out.println(result);
  }
}

