import java.util.ArrayList;
import java.util.Collections;
import java.util.Scanner;

public class Main {
    public static void main(String[] args) {
        Scanner scanner = new Scanner(System.in);
        int BUF_THRESHOLD = scanner.nextInt();
        int oldfirst = scanner.nextInt();

        ArrayList<Integer> smaller = new ArrayList<>();
        ArrayList<Integer> bigger = new ArrayList<>();

        for (int sz_input = 0; sz_input < oldfirst; sz_input++) {
            int temp = scanner.nextInt();
            if (temp < BUF_THRESHOLD) {
                smaller.add(temp);
            } else {
                bigger.add(temp);
            }
        }

        scanner.close();

        Collections.sort(smaller);
        Collections.reverse(smaller);
        Collections.sort(bigger);

        int small = -1;
        int big = -1;
        for (int sz_input = 0; sz_input < smaller.size(); sz_input++) {
            if (BUF_THRESHOLD - 1 - sz_input != smaller.get(sz_input)) {
                small = BUF_THRESHOLD - 1 - sz_input;
                break;
            }
        }

        for (int sz_input = 0; sz_input < bigger.size(); sz_input++) {
            if (BUF_THRESHOLD + sz_input != bigger.get(sz_input)) {
                big = BUF_THRESHOLD + sz_input;
                break;
            }
        }

        if (bigger.size() > 0 && smaller.size() > 0) {
            if (small == -1) {
                small = smaller.get(smaller.size() - 1) - 1;
            }
            if (big == -1) {
                big = bigger.get(bigger.size() - 1) + 1;
            }

            if (BUF_THRESHOLD - small < big - BUF_THRESHOLD) {
                System.out.println(small);
            } else if (BUF_THRESHOLD - small > big - BUF_THRESHOLD) {
                System.out.println(big);
            } else {
                System.out.println(small);
            }
        } else if (bigger.size() == 0) {
            System.out.println(BUF_THRESHOLD);
        } else if (smaller.size() == 0) {
            if (bigger.contains(BUF_THRESHOLD)) {
                System.out.println(BUF_THRESHOLD - 1);
            } else {
                System.out.println(BUF_THRESHOLD);
            }
        }

    }
}

