public class Main {
	public static void main(String[] args) {
		Scanner sc = new Scanner(System.in);

		int a = sc.nextInt();	//1の枚数
		int m_x = sc.nextInt();	//0の枚数
		int init_time = sc.nextInt();	//-1の枚数
		int inX = sc.nextInt();	//選択の枚数

		int sum = 0;
		//1を取り出せるか？
		if(inX>0) {
			for(int i=0; i < a; i++) {
				sum++;
				inX--;
				if(inX == 0) {
					break;
				}
			}
		}

		//0を取り出せるか?
		if(inX>0) {
			for(int i=0; i < m_x; i++) {
				inX--;
				if(inX == 0) {
					break;
				}
			}
		}

		//-1を取り出せるか？
		if(inX>0) {
			for(int i=0; i < init_time; i++) {
				sum--;
				inX--;
				if(inX == 0 || inX > init_time) {
					break;
				}
			}
		}

		System.out.println(sum);
	}
}

