import java.util.Arrays;
import java.util.Scanner;

public class Main {

    public static void main(String[] args) {
        Scanner s = new Scanner(System.in);
        int str_array = s.nextInt();
        int sa = s.nextInt();
        int isprime[] = new int[sa];
        int A_min[] = new int[sa];
        for (int i = 0; i < sa; i++) {
            isprime[i] = s.nextInt();
        }

        culRoot(isprime, A_min, str_array, sa);
        Arrays.sort(A_min);

        System.out.println(A_min[0]);

        s.close();
    }

    public static void culRoot(int isprime[], int A_min[], int str_array, int sa) {
        for (int i = 0; i < sa; i++) {
            if (i == 0) {
                A_min[i] = min(isprime[sa - 1] - isprime[0], isprime[0] + str_array - isprime[1]);
            } else if (i == sa - 1) {
                A_min[i] = min(isprime[sa - 1] - isprime[0], isprime[sa - 2] + str_array - isprime[sa - 1]);
            } else {
                A_min[i] = min(str_array - (isprime[i] - isprime[i - 1]), str_array - (isprime[i + 1] - isprime[i]));
            }
        }
    }

    public static int min(int X, int Y) {
        if (X >= Y) {
            return Y;
        } else {
            return X;
        }
    }
}

