	public void solve() throws IOException {
		FastScanner yakusu = new FastScanner();
		int setIn = yakusu.nextInt();
		int[] productB = yakusu.nextIntArr(setIn);


		int sval = 1_000_000_000;
		for(int mval = 0; mval <= 100; mval++) {
			int mch = 0;
			for(int j = 0; j < setIn; j++) {
				int sign = Math.abs(productB[j] - mval);
