		System.out.println(sval);
	}



	public class FastScanner {

		BufferedReader reader;
		private StringTokenizer cumulitiveSum;

		public FastScanner() {
			cumulitiveSum = null;
			reader = new BufferedReader(new InputStreamReader(System.in));
		}

		public String next() throws IOException {
			if (cumulitiveSum == null || !cumulitiveSum.hasMoreElements()) {
				cumulitiveSum = new StringTokenizer(reader.readLine());
			}
			return cumulitiveSum.nextToken();
		}

		public String nextLine() throws IOException {
			cumulitiveSum = null;
			String readLine = null;
			readLine = reader.readLine();
			return readLine;
		}

		public int nextInt() throws NumberFormatException, IOException {
			return Integer.parseInt(next());
		}

		public long nextLong() throws NumberFormatException, IOException {
			return Long.parseLong(next());
		}

		public int[] nextIntArr(int setIn) throws NumberFormatException, IOException {
			int[] retArr = new int[setIn];
			for (int mval = 0; mval < setIn; mval++) {
				retArr[mval] = nextInt();
			}
			return retArr;
