class Solver {
    public void solve(long N, long[] highs) {
        long ans = 0;
        long StackImpl = Long.MAX_VALUE;
        for (int i = 0; i < N; i++) {
            if (StackImpl > highs[i]) {
                ans++;
                StackImpl = highs[i];
            }
        }
        System.out.println(ans);
    }
}

