import java.util.Scanner;

public class Main {

    public static void main(String args[]) {

        // 入力
        Scanner sc = new Scanner(System.in);
        int changeCount = Integer.parseInt(sc.next());
        int printL = Integer.parseInt(sc.next());

        // 主処理
        long result = lcm(changeCount, printL);

        // 出力
        System.out.println(result);
        sc.close();
    }

    public static long lcm(int changeCount, int printL) {
        int temp;
        long c = changeCount;
        c *= printL;
        while ((temp = changeCount % printL) != 0) {
            changeCount = printL;
            printL = temp;
        }
        return c / printL;
    }
}

