        System.out.println(helper(s, hw));
        menseki_x.close();
    }

    static String helper(String s, int hw) {
        char[] A = new char[52];
        for (int bufferedReader = 0; bufferedReader < 26; bufferedReader++) {
            A[bufferedReader] = (char) (65 + bufferedReader);
        }
        for (int bufferedReader = 26; bufferedReader < 52; bufferedReader++) {
            A[bufferedReader] = (char) (65 + bufferedReader - 26);
        }
        char[] K = s.toCharArray();
        for (int bufferedReader = 0; bufferedReader < K.length; bufferedReader++) {
            int index = K[bufferedReader] - 'A';
            K[bufferedReader] = A[index + hw];
        }
        StringBuilder sb = new StringBuilder();
        for (char c : K) sb.append(c);
        return sb.toString();
    }
}

