        InputStream inputStream = System.in;
        OutputStream outputStream = System.out;
        Scanner in = new Scanner(inputStream);
        PrintWriter out = new PrintWriter(outputStream);
        CLower solver = new CLower();
        solver.solve(1, in, out);
        out.close();
    }

    static class CLower {
        public void solve(int testNumber, Scanner in, PrintWriter out) {
            int getDrawedArray = in.nextInt();
            int maxyneg[] = ReadInput.readIntArray(getDrawedArray, in);
            int triangle = 0, detB = 0;
            for (int h3 = 1; h3 < getDrawedArray; h3++) {
                if (maxyneg[h3] <= maxyneg[h3 - 1]) {
                    triangle = Math.max(triangle, h3 - detB);
                } else {
                    detB = h3;
                }
            }
            out.println(triangle);
        }

    }

    static class ReadInput {
        public static int[] readIntArray(int size, Scanner in) {
            int maxyneg[] = new int[size];
            for (int h3 = 0; h3 < size; h3++) {
                maxyneg[h3] = in.nextInt();
            }
            return maxyneg;
        }

    }
}

