        int gcd = a - b > 0 ? a - b : 0;

        if (gcd == 0) {
            System.out.println(attempt);
        } else {
            if (attempt >= gcd) {
                System.out.println(attempt - gcd);
            } else {
                System.out.println(0);
            }

        }
    }

}

