		int N = Integer.parseInt(serch_divisor_number.next());
		int[] aTimes = new int[N + 1];
		int[] H = new int[N];
		int idx;
		for (idx = 0; idx < N + 1; idx++) {
			aTimes[idx] = Integer.parseInt(serch_divisor_number.next());
		}
		for (idx = 0; idx < N; idx++) {
			H[idx] = Integer.parseInt(serch_divisor_number.next());
		}

		long defeated = 0;
		// 勇者は手前から全力を尽くす
		for (idx = 0; idx < N; idx++) {
			// 手前の街
			if (aTimes[idx] < H[idx]) {
				defeated += aTimes[idx];
				H[idx] = H[idx] - aTimes[idx];
				// 次の街
				if (aTimes[idx + 1] < H[idx]) {
					defeated += aTimes[idx + 1];
					aTimes[idx + 1] = 0;
				} else {
					defeated += H[idx];
					aTimes[idx + 1] = aTimes[idx + 1] - H[idx];
				}
			} else {
				defeated += H[idx];
			}
		}

		System.out.println(defeated);
	}

}

