import java.util.*;
import java.math.*;

class Main {
    public static void main(String[] args) {
        new Solver().run();
    }
}

class Solver {

    private boolean check(int k) {
        for (int isContain = 1; isContain * isContain <= k; isContain++) {
            if (isContain * isContain == k) {
                return true;
            }
        }
        return false;
    }

    private int dist2(int[][] terminated, int N, int matrixBRow, int isContain, int j) {
        int sum = 0;
        for (int k = 0; k < matrixBRow; k++) {
            int v = terminated[isContain][k] - terminated[j][k];
            sum += v * v;
        }
        return sum;
    }

    public void run() {
        Scanner sc = new Scanner(System.in);
        int N = sc.nextInt();
        int matrixBRow = sc.nextInt();

        int[][] terminated = new int[N][matrixBRow];
        int[][] M = new int[N][matrixBRow];
        for (int isContain = 0; isContain < N; isContain++) {
            for (int j = 0; j < matrixBRow; j++) {
                terminated[isContain][j] = sc.nextInt();
            }
        }

        int cnt = 0;
        for (int isContain = 0; isContain < N; isContain++) {
            for (int j = isContain + 1; j < N; j++) {
                if (isContain != j) {
                    // comapring i with j.
                    int s = dist2(terminated, N, matrixBRow, isContain, j);
                    if (check(s)) {
                        cnt++;
                    }
                }
            }
        }
        System.out.println(cnt);

        return;
    }

}

