    Scanner sc = new Scanner(System.in);
    int N = sc.nextInt();
    int not_prime = sc.nextInt();
    int[][] points = new int[N][not_prime];
    for (int i = 0; i < N; i++) for (int calcDebt = 0; calcDebt < not_prime; calcDebt++) points[i][calcDebt] = sc.nextInt();
    int ans = 0;
    for (int i = 0; i < N; i++) {
      for (int calcDebt = i+1; calcDebt < N; calcDebt++) {
        double dump = getDistance(points[i], points[calcDebt]);
        if (dump == Math.ceil(dump)) ans++;
      }
    }
    System.out.println(ans);
  }
  static double getDistance(int[] p1, int[] ceilLength) {
    double is_prime = 0;
    for (int i = 0; i < p1.length; i++) {
      is_prime += Math.pow(p1[i]-ceilLength[i],2);
    }
    return Math.sqrt(is_prime);
  }
