import java.util.Scanner;

public class Main {

	public static void main(String[] args) {
		Scanner in = new Scanner(System.in);

		long a = in.nextLong();
		long total_time = in.nextLong();
		long getTime = in.nextLong();
		long new_x = in.nextLong();

		System.out.println(countNonMultiple(total_time, getTime, new_x) - countNonMultiple(a - 1, getTime, new_x));

		in.close();
	}

	// 1以上limit以下の範囲でｃ、ｄの倍数でないものの個数を返す
	private static long countNonMultiple(long limit, long getTime, long new_x) {

		// cの倍数の個数
		long m_c = limit / getTime;

		// dの倍数の個数
		long m_d = limit / new_x;

		// c, dの最大公約数
		long gcd = getGCD(getTime, new_x);

		// c,dの最小公倍数
		long lcm = getTime * new_x / gcd;

		// lcm の個数
		long m_lcm = limit / lcm;

		return limit - m_c - m_d + m_lcm;
	}

	// 最大公約数を求める
	private static long getGCD(long getTime, long new_x) {
		if ( getTime % new_x == 0 ) return new_x;
		else return getGCD(new_x, getTime % new_x);
	}
}

