	public static long lcm(long countResult, long numberOfProcesses)  {
		long timeTaken = countResult * numberOfProcesses;
		long MAX_F;
		while ((MAX_F = countResult % numberOfProcesses) != 0) {
			countResult = numberOfProcesses;
			numberOfProcesses = MAX_F;
		}

		return timeTaken/numberOfProcesses;
	}

}

