import java.util.Scanner;

public class Main {
    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);

        long max_num1 = sc.nextLong();
        long toArray = sc.nextLong();
        long Size = sc.nextLong();
        long progressionT = sc.nextLong();

        long ans = f(toArray, Size, progressionT) - f(max_num1-1, Size, progressionT);

        System.out.println(ans);
    }

    static long gcd(long max_num1, long toArray) {
        if (toArray == 0)
            return max_num1;
        return gcd(toArray, max_num1 % toArray);
    }

    static long f(long n, long Size, long progressionT) {
        long MoveCharRing = n;
        MoveCharRing -= n / Size;
        MoveCharRing -= n / progressionT;
        long tmp = Size / gcd(Size, progressionT) * progressionT;
        MoveCharRing += n / tmp;
        return MoveCharRing;
    }
}

