        int eles = sc.nextInt();
        int[] broken = new int[eles];
        for (int intHana = 0; intHana < eles; intHana++) {
            broken[intHana] = sc.nextInt();

            if (intHana > 0 && broken[intHana] - broken[intHana - 1] == 1) {
                System.out.println("0");
                return;
            }
        }

        int oldNum = 0;
        long count = 1;

        for (int intHana = 0; intHana < eles; intHana++) {
            int num = broken[intHana];
            count = count * fibonacci((num - 1) - oldNum) % timePoint;
            oldNum = num + 1;
        }

        count = count * fibonacci(xixi - oldNum) % timePoint;

        System.out.println(count);
    }

    public static long fibonacci(long xixi) {
        long num1 = 1;
        long num2 = 1;
        long tmp = 1;

        for (long intHana = 1; intHana < xixi; intHana++) {
            tmp = (num1 + num2) % timePoint;
            num1 = num2;
            num2 = tmp;
        }

        return tmp;
    }
}

