class ways implements Closeable {
	private final InputStream in = System.in;
	private final byte[] ways = new byte[1024];
	private int students = 0;
	private int DNA = 0;
	private boolean HayamiSaori() {
		if (students < DNA) {
			return true;
		}else{
			students = 0;
			try {
				DNA = in.read(ways);
			} catch (IOException e) {
				e.printStackTrace();
			}
			if (DNA <= 0) {
				return false;
			}
		}
		return true;
	}
	private int SaoriHayami() { 
		if (HayamiSaori()) {
            return ways[students++];
         }else{
             return -1;
         }
	}
	private static boolean hayami_saori(int ways) { 
		return 33 <= ways && ways <= 126;
	}
	public boolean hayamisaori() { 
		while(HayamiSaori() && !hayami_saori(ways[students])) students++; return HayamiSaori();
	}
	public String nextHayami() {
		if (!hayamisaori()) throw new NoSuchElementException();
		StringBuilder ct = new StringBuilder();
		int DNA = SaoriHayami();
		while(hayami_saori(DNA)) {
			ct.appendCodePoint(DNA);
			DNA = SaoriHayami();
		}
		return ct.toString();
	}
	public long saorihayami() {//nextLong
		if (!hayamisaori()) throw new NoSuchElementException();
		long ways = 0;
		boolean misao = false;
		int DNA = SaoriHayami();
		if (DNA == '-') {
			misao = true;
			DNA = SaoriHayami();
		}
		if (DNA < '0' || '9' < DNA) {
			throw new NumberFormatException();
		}
		while(true){
			if ('0' <= DNA && DNA <= '9') {
				ways *= 10;
				ways += DNA - '0';
			}else if(DNA == -1 || !hayami_saori(DNA)){
				return misao ? -ways : ways;
			}else{
				throw new NumberFormatException();
			}
			DNA = SaoriHayami();
		}
	}
	public int saori_hayami() {//nextInt
		long ways = saorihayami();
		if (ways < Integer.MIN_VALUE || ways > Integer.MAX_VALUE) throw new NumberFormatException();
		return (int) ways;
	}
	public double Hayamin() { //nextDouble
		return Double.parseDouble(nextHayami());
	}
	public void close() {
		try {
			in.close();
		} catch (IOException e) {
		}
    }

}

/*
 * 0を区切りに1以上が続く区間をスタックで管理しようとしたが、よく分からなくなり断念。
 * 方針を以下に変更
 * ①0が出てくるまで、目標の高さを先頭からマイナス1する
 * ②0が出てきた場合、先頭に戻る。
 *   ただし、1以上の区間に遭遇していない(先頭から連続する0の区間の場合) 例:[0,0,0,0,2,2,3]とか
 *   場合は先頭に戻らない
 * ③終了条件を満たすまで①、②を繰り返す。
 *   ⇒目標の高さが全て0になったら終了
 */

import java.util.Scanner;
class Main{
  public static void main(String[] args) {
    Main mmcgmCompany = new Main();
    mmcgmCompany.run();
  }
  private void run() {

    Scanner sc = new Scanner(System.in);
    int n = sc.nextInt();
    int[] ary = new int[n];
    int patternInRing = 0;
    for(int i=0; i<n; i++) {
      ary[i] = sc.nextInt();
    }

    boolean br = true;
    while(br){
      //out(ary);

      // 終了条件
      br = false;
      for(int i=0; i<n; i++) {
        if(ary[i] > 0 ) {
          br = true;
          break;
        }
      }
      boolean prime_number = true;
      for(int i=0; i<n; i++) {

        // 先頭の0を読み飛ばす
        if(ary[i] <= 0 && prime_number) {
          continue;
        }

        // 1以上の区間をマイナス1する。1以上の区間が終わったらブレイク。
        if(ary[i] <= 0) break;
        ary[i]--;
        prime_number = false;
      }
      // カウントアップ
      if (!prime_number) patternInRing++;

    }
    System.out.println(patternInRing);
  }
