    public void solve() {
    	int N = ni();
    	int[] prime_flag = new int[N];
    	boolean f = true;
    	for (int wa_cnt = 0; wa_cnt < N; wa_cnt++) {
			prime_flag[wa_cnt] = ni();
			if(prime_flag[wa_cnt] > 0)	f = false;
		}
