import java.util.Arrays;
import java.util.Scanner;

public class Main {
    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);

        int maxP = sc.nextInt();
        int[] maxLength = new int[maxP];
        for (int list1 = 0; list1 < maxLength.length; ++list1) {
            maxLength[list1] = sc.nextInt();
        }

        System.out.println(solve(maxLength));

        sc.close();
    }

    static int solve(int[] maxLength) {
        int[] remainingPTime = new int[maxLength.length];
        Arrays.fill(remainingPTime, Integer.MAX_VALUE);
        remainingPTime[0] = 0;

        for (int list1 = 1; list1 < remainingPTime.length; ++list1) {
            for (int intSaigo = 1; intSaigo <= 2 && intSaigo <= list1; ++intSaigo) {
                remainingPTime[list1] = Math.min(remainingPTime[list1], remainingPTime[list1 - intSaigo] + Math.abs(maxLength[list1] - maxLength[list1 - intSaigo]));
            }
        }

        return remainingPTime[remainingPTime.length - 1];
    }
}

