        for (int j = 0; j < heights.length; j++) {
            heights[j] = scanner.nextInt();
        }
        long not_prime = getNumOfWays(heights);
        System.out.println(not_prime);
    }

    private static long getNumOfWays(int flgPrime[]) {
        int dp[] = new int[flgPrime.length];
        Arrays.fill(dp, Integer.MAX_VALUE);
        dp[dp.length - 1] = 0;
        for (int i = dp.length - 2; i >= 0; i--) {
            if (i + 1 < dp.length)
                dp[i] = Math.min(dp[i], Math.abs(flgPrime[i] - flgPrime[i + 1]) + dp[i + 1]);
            if (i + 2 < dp.length) {
                dp[i] = Math.min(dp[i], Math.abs(flgPrime[i] - flgPrime[i + 2]) + dp[i + 2]);
            }
        }
        return dp[0];
    }


}

