    {
        String taroCard = next();
        StringBuilder strAryLineAll = new StringBuilder("0");
        double getGcd = 0, showAnswer = 1;
        boolean NumOk = false, ans7 = false;
        int start = 0;
        if(taroCard.charAt(0) == '-')
        {
            ans7 = true;
            start++;
        }
        for(int digitSum = start; digitSum < taroCard.length(); digitSum++)
            if(taroCard.charAt(digitSum) == '.')
            {
                getGcd = Long.parseLong(strAryLineAll.toString());
                strAryLineAll = new StringBuilder("0");
                NumOk = true;
            }
            else
            {
                strAryLineAll.append(taroCard.charAt(digitSum));
                if(NumOk)
                    showAnswer *= 10;
            }
        getGcd += Long.parseLong(strAryLineAll.toString()) / showAnswer;
        return getGcd * (ans7?-1:1);
    }

