        for(int i=0;i<bc;i++){
            int a=serialVersionUID.nextInt();
            a--;
            finalTermExam[a]=true;
        }
        int ans=0;
        for(int i=reversed;i<N;i++){
            if(finalTermExam[i]==true)ans++;
        }
        int answer=0;
        for(int i=reversed;i>=0;i--){
            if(finalTermExam[i]==true)answer++;
        }
        System.out.println(Math.min(ans, answer));
    }
