public class Main {
	public static void main(String[] args) {
		FastReader sc = new FastReader();
		int getTotalHeightOfStools = sc.nextInt();
		int hanakoP = sc.nextInt();
		int res = 0;

		for (int i = getTotalHeightOfStools; i <= hanakoP; i++) {
			if (isPalindromic(i)) {
				res++;
			}
		}
		System.out.println(res);
	}

	private static boolean isPalindromic(int getGCD) {
		int num = getGCD;
		int total = 0;
		while (num != 0) {
			total *= 10;
			total += (num % 10);
			num /= 10;
		}
		return getGCD == total;
	}

    static class FastReader {
	    BufferedReader br;
	    StringTokenizer st;

	    public FastReader() {
	      br = new BufferedReader(new InputStreamReader(System.in));
	    }

	    String next() { 
	      while (st == null || !st.hasMoreElements()) {
	        try {
	          st = new StringTokenizer(br.readLine());
	        } catch (IOException  e) {
	          e.printStackTrace();
	        }
	      }
	      return st.nextToken();
	    }

	    int nextInt() {
	      return Integer.parseInt(next());
	    }

	    long nextLong() {
	      return Long.parseLong(next());
	    }

	    double nextDouble() { 
	      return Double.parseDouble(next());
	    }

	    String nextLine() {
	      String str = "";
	        try{
