import java.io.BufferedReader;
import java.io.InputStreamReader;
import java.util.StringTokenizer;

public class Main {
    public static void main(String[] args) throws Exception {
        BufferedReader input = new BufferedReader(new InputStreamReader(System.in));
        int lengthOfCircumference = Integer.parseInt(input.readLine());

        int[][] values = new int[2][lengthOfCircumference];
        int[][] isprime = new int[2][lengthOfCircumference];

        StringTokenizer tokenizer;

        for (int items = 0; items < 2; items++) {
            tokenizer = new StringTokenizer(input.readLine());
            for (int j = 0; j < lengthOfCircumference; j++) {
                values[items][j] = Integer.parseInt(tokenizer.nextToken());
            }
        }

        isprime[0][0] = values[0][0];

        for (int items = 0; items < 2; items++) {
            for (int j = 0; j < lengthOfCircumference; j++) {
                    isprime[items][j] = values[items][j] + Math.max(getValues(items - 1, j, isprime), getValues(items, j - 1, isprime));
            }
        }

        System.out.println(isprime[1][lengthOfCircumference- 1]);

    }



    public static boolean checkIndex (int x, int y, int lengthOfCircumference){
        return x > -1 && y > -1 && x < 2 && y < lengthOfCircumference;
    }

    public static int getValues(int x, int y, int [][] values){

        if (checkIndex(x, y, values[0].length)){
            return values[x][y];
        }

        return 0;

    }
}

