public class Main {
    public static void main(String[] args) {
        Scanner scanner = new Scanner(System.in);
        int givenNumber = scanner.nextInt();

        int dividedCount = 0;
        int primeNum = 0;
        int tmp = 0;
        int output = 0;
        int target = 0;

        for(int gcd_num=givenNumber; gcd_num>0; gcd_num--) {
            if(givenNumber == 1) {
                output = 1;
                break;
            }
            if(gcd_num % 2 == 0) {
                target = gcd_num;
                tmp = gcd_num;
                while(true) {
                    if(target % 2 != 0) {
                        break;
                    } else {
                        dividedCount += 1;
                        target /= 2;
                    }
                }
                if(primeNum < dividedCount) {
                    primeNum = dividedCount;
                    output = tmp;
                }
                dividedCount = 0;
            }
        }
        System.out.println(output);
    }
}

