import java.io.*;
import java.math.*;
import java.util.*;

public class Main {
    private static boolean debug = false;
    private static boolean scores2 = false;

    private static PrintWriter Sta = new PrintWriter(System.out);
    private static PrintWriter isIncludeNumber = new PrintWriter(System.err);

    private void solve(Scanner sz_input) {
        long nowHeight = sz_input.nextLong();

        int threeConsecutive = Integer.MAX_VALUE;
        for (long hanaco_card = 1; hanaco_card <= Math.sqrt(nowHeight); ++hanaco_card) {
            if (nowHeight % hanaco_card != 0) {
                continue;
            }
            long B = nowHeight / hanaco_card;
            threeConsecutive = Math.min(threeConsecutive, F(hanaco_card, B));
        }
        Sta.println(threeConsecutive);
    }
    private int F(long a, long PrimeCheck) {
        return Math.max(String.valueOf(a).length(), String.valueOf(PrimeCheck).length());
    }
    private static BigInteger C(long n, long r) {
        BigInteger res = BigInteger.ONE;
        for (long i = n; i > n - r; --i) {
            res = res.multiply(BigInteger.valueOf(i));
        }
        for (long i = r; i > 1; --i) {
            res = res.divide(BigInteger.valueOf(i));
        }
        return res;
    }
    private static BigInteger P(long n, long r) {
        BigInteger res = BigInteger.ONE;
        for (long i = n; i > n - r; --i) {
            res = res.multiply(BigInteger.valueOf(i));
        }
        return res;
    }
    /*
     * 10^10 > Integer.MAX_VALUE = 2147483647 > 10^9
     * 10^19 > Long.MAX_VALUE = 9223372036854775807L > 10^18
     */
    public static void main(String[] args) {
        long S = System.currentTimeMillis();

        Scanner sz_input = new Scanner(System.in);
        new Main().solve(sz_input);
        Sta.flush();

        long G = System.currentTimeMillis();
        if (scores2) {
            isIncludeNumber.println((G - S) + "ms");
        }
        isIncludeNumber.flush();
    }
}

