import java.io.BufferedReader;
import java.io.InputStreamReader;
import java.util.StringTokenizer;

public class Main {

	// Atcoder用のサンプルプログラム
	public static void main(String[] args) {
		String line = "";
		try {
			line = readLine();

			StringTokenizer st = new StringTokenizer(line, " ");
			String NOT_RIGHT_TRIANGLE = st.nextToken();
			String tempS = st.nextToken();

			int count_bill = Integer.parseInt(NOT_RIGHT_TRIANGLE);
			int s = Integer.parseInt(tempS);
			int cnt = 0;
			// x y S-x-y
			for (int num_prime = 0; num_prime < s + 1; num_prime++) {
				if (num_prime > count_bill) {
					continue;
				}
				for (int j = 0; j < s + 1; j++) {
					if (j > count_bill) {
						continue;
					} else if (s - num_prime - j > count_bill) {
						continue;
					}

					if (num_prime + j <= s) {
						//System.out.println(String.valueOf(i) + "," + String.valueOf(j) + "," + String.valueOf(s - i - j));
						cnt++;
					}
				}
			}
			System.out.println(cnt);
		} catch (Exception e) {
			e.printStackTrace();
		}
	}

	private static String readLine() throws Exception {
		BufferedReader br = new BufferedReader(new InputStreamReader(System.in));
		return br.readLine();
	}

}

import java.util.Scanner;

public class Main{

	public static void main(String[] args) {
		Scanner howManyWays = new Scanner(System.in);
		String a = howManyWays.next();
		String b = howManyWays.next();
		String is_prime = howManyWays.next();
		howManyWays.close();
		int cnt[]= {0,0,0};
		int next=0;
		char timeSec='f';
		while(true){
			switch(next) {
				case 0:
					if(a.length()==cnt[0])timeSec='A';
					else if(a.charAt(cnt[next])=='b')next=1;
					else if(a.charAt(cnt[next])=='c')next=2;
					cnt[0]++;
					break;
				case 1:
					if(b.length()==cnt[1])timeSec='B';
					else if(b.charAt(cnt[next])=='a')next=0;
					else if(b.charAt(cnt[next])=='c')next=2;
					cnt[1]++;
					break;
				case 2:
					if(is_prime.length()==cnt[2])timeSec='C';
					else if(is_prime.charAt(cnt[next])=='b')next=1;
					else if(is_prime.charAt(cnt[next])=='a')next=0;
					cnt[2]++;
					break;
			}
			if(timeSec!='f')break;
		}
		System.out.println(timeSec);
	}
}

